fn solve(nums: Vec<i8>) -> Vec<char> {
    // We expect exactly three numbers
    assert!(nums.len() == 3, "Expected exactly three integers");

    // Sort in non-decreasing order
    let mut v = nums;
    v.sort_unstable();
    let a = v[0];
    let b = v[1];
    let c = v[2];

    // Check the required conditions
    let yes = 
        // at least one is 1
        a == 1
        // at least two are 2
        || (a == 2 && b == 2)
        // exactly (2,4,4)
        || (a == 2 && b == 4 && c == 4)
        // exactly (3,3,3)
        || (a == 3 && b == 3 && c == 3);

    if yes {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

fn main() {
    // Example usages
    let cases = vec![
        vec![1, 150, 1500], // contains a 1 -> YES
        vec![2, 2, 10],     // two 2's -> YES
        vec![2, 4, 4],      // (2,4,4) -> YES
        vec![3, 3, 3],      // (3,3,3) -> YES
        vec![2, 3, 5],      // none of the above -> NO
    ];

    for nums in cases {
        println!("{:?} -> {:?}", nums, solve(nums));
    }
}